/**
 * @name XML External Entity (XXE) injection in lxml
 * @description Parsing untrusted XML with external entity processing enabled can lead to XXE attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-injection
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for XML parsing with potentially unsafe configurations
    exists(DataFlow::CallCfgNode call |
      // lxml.etree module functions
      call = API::moduleImport("lxml").getMember("etree").getMember(["XML", "fromstring", "parse", "XMLParser"]).getACall() or
      call = API::moduleImport("lxml").getMember("ElementTree").getACall() or
      // lxml.html module functions
      call = API::moduleImport("lxml").getMember("html").getMember(["fromstring", "parse", "HTMLParser"]).getACall()
    |
      // Get the first argument (XML data) as the sink
      sink = call.getArg(0)
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML parsing with potentially untrusted input from $@.", source.getNode(), "user input"

/**
 * @name XPath injection in lxml
 * @description Using untrusted input in XPath expressions can lead to XPath injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xpath-injection
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for XPath evaluation with potentially untrusted input
    exists(DataFlow::CallCfgNode call |
      // lxml XPath methods
      call = API::moduleImport("lxml").getMember("etree").getMember("_Element").getMember("xpath").getACall() or
      call = API::moduleImport("lxml").getMember("etree").getMember("XPath").getACall() or
      call = API::moduleImport("lxml").getMember("html").getMember("HtmlElement").getMember("xpath").getACall()
    |
      // Get the XPath expression argument (usually first argument)
      sink = call.getArg(0)
    )
  }
}

module XPathFlow = TaintTracking::Global<XPathConfig>;
import XPathFlow::PathGraph

from XPathFlow::PathNode source, XPathFlow::PathNode sink
where XPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XPath injection from $@.", source.getNode(), "user input"

/**
 * @name Cross-site scripting (XSS) in lxml HTML processing
 * @description Processing untrusted HTML without proper sanitization can lead to XSS vulnerabilities
 * @kind path-problem
 * @problem.severity error
 * @id py/xss-injection
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XSSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTML parsing functions that could process untrusted content
    exists(DataFlow::CallCfgNode call |
      // lxml.html parsing functions
      call = API::moduleImport("lxml").getMember("html").getMember(["fromstring", "parse", "document_fromstring"]).getACall() or
      // lxml.html.HTMLParser
      call = API::moduleImport("lxml").getMember("html").getMember("HTMLParser").getACall() or
      // lxml.html.html5parser functions
      call = API::moduleImport("lxml").getMember("html").getMember("html5parser").getMember(["fromstring", "parse"]).getACall()
    |
      // Get the first argument (HTML data) as the sink
      sink = call.getArg(0)
    )
  }
}

module XSSFlow = TaintTracking::Global<XSSConfig>;
import XSSFlow::PathGraph

from XSSFlow::PathNode source, XSSFlow::PathNode sink
where XSSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTML parsing with potentially untrusted input from $@.", source.getNode(), "user input"

/**
 * @name Command injection in lxml
 * @description Using untrusted input in system commands can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for command execution sinks
    exists(DataFlow::CallCfgNode call |
      // os.system, os.popen, subprocess.call, etc.
      call = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall() or
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() or
      call = API::moduleImport("commands").getMember(["getoutput", "getstatusoutput"]).getACall()
    |
      // Get command argument as sink
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in lxml file operations
 * @description File operations with user-controlled paths could lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for file operations in lxml
    exists(DataFlow::CallCfgNode call |
      // File opening/reading operations
      call = API::moduleImport("lxml").getMember("etree").getMember("parse").getACall() or
      call = API::moduleImport("lxml").getMember("html").getMember("parse").getACall() or
      // General file operations that might be used
      call = API::builtin("open").getACall()
    |
      // Get the path argument
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File operation with potentially untrusted path from $@.", source.getNode(), "user input"
